int szukam = 100;
int p = 0, k = tab.length;
while ( p <= k ) {
    int mid = (p + k) / 2;
    if (tab[mid] < szukam) {
        p = mid + 1;
    }
    else if (tab[mid] > szukam) {
        k = mid - 1;
    }
    else {
        System.out.println("Znalazlem wartosc " + szukam + " na pozycji " + mid);
        break;
    }
}
if (p > k) {
    System.out.println("Nie znalazlem wartosci " + szukam + " w tablicy.");
}

